@push('scripts')<script>(()=>{const drawer=document.getElementById('applicationDrawer'),open=document.getElementById('openApplication'),close=document.getElementById('closeApplication');if(!drawer)return;const setOpen=value=>{drawer.classList.toggle('open',value);drawer.setAttribute('aria-hidden',String(!value));document.body.classList.toggle('drawer-open',value)};open?.addEventListener('click',()=>setOpen(true));close?.addEventListener('click',()=>setOpen(false));drawer.addEventListener('click',event=>{if(event.target===drawer)setOpen(false)});document.addEventListener('keydown',event=>{if(event.key==='Escape')setOpen(false)});if(drawer.classList.contains('open'))document.body.classList.add('drawer-open')})();</script>@endpush
@push('scripts')<script>(()=>{const recommendations=document.getElementById('recommendationDrawer');if(!recommendations)return;const close=()=>{recommendations.classList.remove('open');recommendations.setAttribute('aria-hidden','true');document.body.classList.remove('drawer-open')};document.body.classList.add('drawer-open');recommendations.querySelectorAll('[data-close-recommendations]').forEach(button=>button.addEventListener('click',close));recommendations.addEventListener('click',event=>{if(event.target===recommendations)close()});document.addEventListener('keydown',event=>{if(event.key==='Escape')close()})})();</script>@endpush
@endsection
